    result={...body,id,farmerId:l.farmerId,buyerId:u.id,buyer:u.name,buyerSubscriptionTier:buyerTier(),location:u.location,crop:l.crop,variety:l.variety,status:'pending',transactionStatus:'offer_review',...offerAssessment(l,body.price),createdAt}; db.offers.push(result);
