function marketNotice() { return `${state.user.demo?`<p class="notice">${t('Demo: mga halimbawang listing, buyer, at distansya. Sa browser na ito lamang nase-save ang demo.','Demo: sample listings, buyers, and distances. Demo changes are saved in this browser only.')}</p>`:''}${state.marketError?`<p role="alert" class="notice">${esc(state.marketError)} <button class="link" onclick="refreshMarket()">${t('Subukan muli','Retry')}</button></p>`:''}`; }
function pageTop(title, back='home') { return `<div class="topbar"><button class="back" onclick="go('${back}')" aria-label="${t('Bumalik','Back')}">${icon('back')}</button><h1>${title}</h1>${authHeader()}</div>`; }
function offerBell() { const count=myOffers().filter(o=>o.status==='pending').length;return `<button class="circle offer-bell" onclick="go('offers')" aria-label="${t('Mga alok ng buyer','Buyer offers')} (${count})">${icon('bell')}${count?`<span class="offer-count">${count}</span>`:''}</button>`; }
function cropOptions(value) { return crops.map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${esc(cropName(c.id))}</option>`).join(''); }
function field(label,id,type,value,extra='') { return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value??'')}" required ${extra}></div>`; }
function submitHarvest() {
  if(state.user.role!=='farmer')return `<section class="page">${pageTop(t('Para sa magsasaka','Farmers only'))}</section>`;
  const d=state.draft || {};
  return `<section class="page soft-page">${pageTop(t('Ilista ang Ani','List harvest'))}<p class="flow-steps"><b>1 ${t('Pananim','Crop')}</b> → 2 AI → 3 ${t('I-publish','Publish')}</p><form class="card" onsubmit="saveHarvest(event)">
    <div class="field"><label for="listCrop">${t('Pananim','Crop')}</label><select id="listCrop">${cropOptions(d.crop)}</select></div>
    ${field(t('Pangalan / variety','Crop / variety name'),'listVariety','text',d.variety,'maxlength="100"')}
    <div class="field"><label for="listType">${t('Uri ng listing','Listing type')}</label><select id="listType">${['pre-harvest','fresh','emergency'].map(id=>`<option value="${id}" ${d.listingType===id?'selected':''}>${listingTypeName(id)}</option>`).join('')}</select></div>
    ${field(t('Dami (kg)','Quantity (kg)'),'listQuantity','number',d.quantity,'min="1" max="1000000000" step="0.01"')}
    <div class="field"><label for="listQuality">${t('Kalidad','Quality')}</label><select id="listQuality">${[['premium','Grade A'],['standard','Grade B'],['low','Grade C']].map(([id,label])=>`<option value="${id}" ${d.quality===id?'selected':''}>${label}</option>`).join('')}</select></div>
    <div class="field"><label for="listMethod">${t('Paraan ng pagtatanim','Farming method')}</label><select id="listMethod">${[['conventional',t('Karaniwan','Conventional')],['organic',t('Organiko','Organic')],['natural',t('Natural','Natural')]].map(([id,label])=>`<option value="${id}" ${d.farmingMethod===id?'selected':''}>${label}</option>`).join('')}</select></div>
    ${field(t('Lokasyon','Location'),'listLocation','text',d.location||state.user.location,'maxlength="100"')}
    ${field(t('Petsa ng ani / inaasahang ani','Harvest / expected harvest date'),'listDate','date',d.harvestDate)}
    <button class="btn wide">${t('Susunod: AI price estimator','Next: AI price estimator')}</button></form></section>`;
}
function saveHarvest(e) {
  e.preventDefault(); if(state.user.role!=='farmer')return;
  const variety=$('#listVariety').value.trim(),location=$('#listLocation').value.trim();
  if(!variety || !location)return toast(t('Punan ang pangalan at lokasyon.','Enter a name and location.'));
  state.draft={draftId:state.draft?.draftId||uid(),crop:$('#listCrop').value,variety,listingType:$('#listType').value,quantity:Number($('#listQuantity').value),quality:$('#listQuality').value,farmingMethod:$('#listMethod').value,location,harvestDate:$('#listDate').value};
  state.listingEstimate=null; go('listingEstimate'); estimateListing();
}
function listingEstimate() {
  const d=state.draft, r=state.listingEstimate;
  if(!d)return `<section class="page">${pageTop(t('Walang draft','No draft'))}<button class="btn" onclick="go('submit')">${t('Ilista ang ani','List harvest')}</button></section>`;
  const totalMinimum=r&&(r.totalMinimum??r.minimum*d.quantity),totalMaximum=r&&(r.totalMaximum??r.maximum*d.quantity);
  return `<section class="page soft-page">${pageTop('AI '+t('Tantiya ng Presyo','Price Estimator'),'submit')}<p class="flow-steps">1 ${t('Pananim','Crop')} → <b>2 AI</b> → 3 ${t('I-publish','Publish')}</p><article class="card"><span class="pill">${listingTypeName(d.listingType)}</span><h2>${esc(d.variety)}</h2><p>${d.quantity} kg · ${esc(d.location)}</p><p class="muted">${esc(d.harvestDate)} · ${esc(d.quality)}</p></article>
    ${r?`<section class="card estimate"><div class="eyebrow">${r.source==='openai'?'AI':t('Gabay sa presyo','Market guidance')}</div><strong class="range">${money(r.minimum)}–${money(r.maximum)}</strong><p>${t('bawat kilo','per kilogram')}</p><div class="estimate-total"><span>${t(`Kabuuang tantiya para sa ${d.quantity} kg`,`Estimated total for ${d.quantity} kg`)}</span><strong>${money(totalMinimum)}–${money(totalMaximum)}</strong></div><p>${esc(r.bestTime||'')}</p><ul class="tips">${(r.tips||[]).map(tip=>`<li>${esc(tip)}</li>`).join('')}</ul></section><p class="notice">${t('Gabay lamang ang tantiya; walang garantisadong presyo o bentahan.','Estimates are guidance only; prices and sales are not guaranteed.')}</p><form onsubmit="publishListing(event)">${field(t('Presyong ilalathala (₱/kg)','Listing price (₱/kg)'),'publishPrice','number',d.price || ((r.minimum+r.maximum)/2).toFixed(2),'min="0.01" max="1000000000" step="0.01"')}<button class="btn wide" ${state.publishing?'disabled':''}>${t('I-publish ang Listing','Publish listing')}</button></form>`:`<section class="card" role="status">${state.estimating?t('Sinusuri ang iyong ani…','Estimating your harvest…'):t('Hindi nakuha ang tantiya. Subukan muli.','Estimate unavailable. Please retry.')}${!state.estimating?`<button class="btn soft wide" onclick="estimateListing()">${t('Subukan muli','Retry')}</button>`:''}</section>`}
    <button class="btn ghost wide" onclick="cancelListing()" ${state.publishing?'disabled':''}>${t('Kanselahin','Cancel')}</button></section>`;
}
async function estimateListing() {
  const draft=state.draft;if(!draft || state.estimating===draft)return;state.estimating=draft;render();
  try {
    let r;
    if(state.user.demo) { const c=crops.find(c=>c.id===draft.crop), base=Math.round(c.base*(draft.quality==='premium'?1.12:draft.quality==='low'?.84:1)); r={minimum:base-2,maximum:base+3,source:'demo',bestTime:t('Halimbawang tantiya para sa demo','Sample estimate for demonstration'),tips:[t('Ihambing sa aktwal na presyo sa inyong lugar.','Compare with actual prices in your area.')]}; }
    else r=await api('/api/estimate',{...draft,language:state.lang});
    if(!Number.isFinite(r.minimum)||!Number.isFinite(r.maximum)||r.minimum<=0||r.maximum<r.minimum)throw new Error('Invalid estimate. Please retry.');
    if(state.draft===draft)state.listingEstimate=r;
  }catch(e){if(state.draft===draft)toast(e.message)}finally{if(state.estimating===draft)state.estimating=null;if(state.page==='listingEstimate')render()}
}
function cancelListing(){state.draft=null;state.listingEstimate=null;go('home');toast(t('Kinansela. Walang nailathala.','Cancelled. Nothing was published.'))}
async function publishListing(e) {
  e.preventDefault();if(!state.draft || !state.listingEstimate || state.publishing)return;
  const price=Number($('#publishPrice').value);if(!Number.isFinite(price)||price<=0)return;
  state.draft.price=price;state.publishing=true;render();
  try{await marketWrite({action:'publish',...state.draft,price,fairMinimum:state.listingEstimate.minimum,fairMaximum:state.listingEstimate.maximum});state.draft=null;state.listingEstimate=null;await refreshMarket();go('profile');toast(t('Nailathala ang listing!','Listing published!'))}catch(e){toast(e.message)}finally{state.publishing=false;render()}
}
function listingCard(l, offer=false) {
  const data=marketData(),saved=data.suppliers.some(x=>x.farmerId===l.farmerId),available=Number.isFinite(Number(l.availableQuantity))?Number(l.availableQuantity):demoAvailable(data,l);
  return `<article class="card harvest"><div class="crop-product-head">${cropPhotoById(l.crop,'crop-card-photo')}<div class="grow"><span class="pill">${listingTypeName(l.listingType)}</span><h3>${esc(l.variety)}</h3><small>${esc(cropName(l.crop))}</small></div></div><p class="muted">${esc(l.farmer)} · ${esc(l.location)}${l.distance?` · ${l.distance} km`:''}</p><p><b>${t('Available na dami','Available quantity')}:</b> ${available} kg <small class="muted">${t(`mula sa ${l.quantity} kg`,`of ${l.quantity} kg`)}</small> · ${esc(l.harvestDate)}</p><p class="small">${esc(l.farmingMethod||'conventional')} · ${esc(l.quality)}</p><strong>${money(l.price)}/kg</strong>${data.premium&&state.user.role==='buyer'?`<button class="link save-supplier" onclick="toggleSupplier('${l.farmerId}')">${saved?'✓ '+t('Naka-save','Saved'):'＋ '+t('I-save ang supplier','Save supplier')}</button>`:''}${offer&&available>0?`<form class="offer-form" onsubmit="sendOffer(event,'${l.id}')">${field(t('Alok (₱/kg)','Offer (₱/kg)'),`price-${l.id}`,'number',l.price,'min="0.01" max="1000000000" step="0.01"')}${field(t('Dami (kg)','Quantity (kg)'),`qty-${l.id}`,'number',available,`min="0.01" max="${available}" step="0.01"`)}<button class="btn soft wide">${t('Ipadala ang alok','Send offer')}</button></form>`:''}</article>`;
}
function buyersPage() {
  const active=state.buyerFilter||'nearest',data=marketData(),query=(state.marketQuery||'').toLowerCase();
  let content;
  if(active==='nearest') {
    const list=data.requests.filter(r=>`${r.buyer} ${cropName(r.crop)} ${r.location}`.toLowerCase().includes(query)).sort((a,b)=>(a.distance??Infinity)-(b.distance??Infinity));
    content=`<p class="notice">${t('Mga pangangailangan ng buyer. Ang may kilalang distansya ang nauuna; ipinapakita ang lokasyon kapag walang distansya.','Buyer needs. Known distances appear first; location is shown when distance is unavailable.')}</p>`+list.map(r=>`<article class="card"><h3>${esc(r.buyer)}</h3><p>${esc(cropName(r.crop))} · ${r.quantity} kg</p><strong>${money(r.price)}/kg</strong><p class="muted">⌖ ${esc(r.location)}${r.distance?` · ${r.distance} km`:''}</p></article>`).join('');
    if(!list.length)content+=emptyState();
  } else {
    const list=data.listings.filter(l=>l.farmerId!==state.user.id && `${l.variety} ${l.farmer} ${l.location}`.toLowerCase().includes(query)).sort((a,b)=>b.price-a.price);
    content=`<p class="muted">${t('Mga listing ng ibang magsasaka','Other farmers’ listings')}</p>`+(list.length?list.map(l=>listingCard(l)).join(''):emptyState());
  }
  return `<section class="page soft-page">${pageTop(t('Mga Buyer at Market','Buyers & Market'))}${marketNotice()}<div class="field"><label for="marketSearch">${t('Maghanap','Search')}</label><input id="marketSearch" value="${esc(state.marketQuery||'')}" onchange="state.marketQuery=this.value;render()" placeholder="${t('Pananim, pangalan, lokasyon','Crop, name, location')}"></div><div class="tabs">${buyerFilterButton('nearest',t('Pinakamalapit','Nearest'))}${buyerFilterButton('price',t('Pinakamataas na presyo','Highest price'))}</div>${content}</section>`;
}
function emptyState(){return `<p class="empty">${t('Wala pang resulta.','No results yet.')}</p>`}
function profile() {
  let html=legacyProfile();if(state.user.role!=='farmer')return html;
  const list=marketData().listings.filter(l=>l.farmerId===state.user.id);
  html=html.replace('<b>14</b>',`<b>${list.length}</b>`);
  const section=`<div class="section-title"><h2>${t('Aking mga Listing','My listings')}</h2><button class="link" onclick="go('submit')">${t('Magdagdag','Add listing')}</button></div>${marketNotice()}${list.length?list.map(l=>listingCard(l)).join(''):emptyState()}`;
  return html.replace('<div class="section-title">',section+'<div class="section-title">');
}
function harvestsPage(){const list=marketData().listings.filter(l=>l.status==='available'&&(l.availableQuantity??l.quantity)>0);return `<section class="page soft-page">${pageTop(t('Mga Ani','Harvest listings'))}${marketNotice()}${list.length?list.map(l=>listingCard(l,state.user.role==='buyer')).join(''):emptyState()}</section>`}
function sponsoredPlacement(){if(state.user?.role!=='buyer'||buyerTier())return '';return `<aside class="card sponsored-placement"><div class="eyebrow">${t('Sponsored · Para sa libreng plan','Sponsored · Free plan')}</div><h3>${t('Mga gamit para sa ligtas na pag-angkat','Supplies for safer produce sourcing')}</h3><p>${t('Halimbawang placement para sa mga kaugnay na agricultural supplier. Ang Pro at Enterprise plans ay walang sponsored content.','Sample placement for a relevant agricultural supplier. Pro and Enterprise plans have no sponsored content.')}</p><button class="link" onclick="go('premium')">${t('Alisin ang ads sa Pro','Remove ads with Pro')} →</button></aside>`}
function buyerHome(){return `<section class="page dashboard">${header()}<section class="card buyer-callout"><h2>${t('Hanapin ang susunod na supply','Find your next supply')}</h2><button class="btn wide" onclick="go('harvests')">${t('Mag-browse ng ani','Browse harvests')}</button><button class="btn soft wide" onclick="go('premium')">✦ ${t('Buyer Premium workspace','Buyer Premium workspace')}</button><button class="btn ghost wide" onclick="go('offers')">${t('Aking mga Alok','My offers')}</button></section>${marketNotice()}${sponsoredPlacement()}<section class="card"><h2>${t('Mag-post ng kailangan','Post a buying request')}</h2><form onsubmit="postRequest(event)"><div class="field"><label for="requestCrop">${t('Pananim','Crop')}</label><select id="requestCrop">${cropOptions()}</select></div>${field(t('Dami (kg)','Quantity (kg)'),'requestQuantity','number','','min="0.01" max="1000000000" step="0.01"')}${field(t('Alok (₱/kg)','Offered price (₱/kg)'),'requestPrice','number','','min="0.01" max="1000000000" step="0.01"')}${field(t('Lokasyon','Location'),'requestLocation','text',state.user.location,'maxlength="100"')}<button class="btn wide">${t('I-post ang request','Post request')}</button></form></section><button class="btn ghost wide" onclick="go('coops')">${t('Mga kooperatiba','Cooperatives')}</button></section>`}
async function submitMarketForm(e,body,success){e.preventDefault();const button=e.target.querySelector('button');if(button.disabled)return;button.disabled=true;try{await marketWrite(body);e.target.reset();await refreshMarket();toast(success)}catch(error){toast(error.message)}finally{button.disabled=false}}
function postRequest(e){return submitMarketForm(e,{action:'request',crop:$('#requestCrop').value,quantity:Number($('#requestQuantity').value),price:Number($('#requestPrice').value),location:$('#requestLocation').value.trim()},t('Na-post ang request.','Request posted.'))}
function sendOffer(e,id){return submitMarketForm(e,{action:'offer',listingId:id,price:Number($(`#price-${id}`).value),quantity:Number($(`#qty-${id}`).value)},t('Naipadala ang alok.','Offer sent.'))}
function statusName(s){return ({pending:t('Naghihintay','Pending'),accepted:t('Tinanggap','Accepted'),rejected:t('Tinanggihan','Rejected'),countered:t('May kontra-alok','Countered')})[s]||s}
function transactionStatusName(s){return ({offer_review:t('Sinusuri ang alok','Offer review'),counter_review:t('Sinusuri ang kontra-alok','Counter review'),confirmed:t('Confirmed','Confirmed'),delivery_assignment:t('Naghahanap ng maghahatid','Finding transport'),delivery_ready:t('Handa nang ihatid','Ready for delivery'),delivery_in_progress:t('Kasulukuyang hinahatid','Delivery in progress'),completed:t('Kumpleto','Completed'),cancelled:t('Kinansela','Cancelled')})[s]||statusName(s)}
function assessmentPanel(o){if(o.status!=='pending')return '';const low=o.assessment==='low';return `<div class="assessment ${low?'low':'fair'}"><b>${low?'⚠️ '+t('Mababa ang alok','Low offer'):'✅ '+t('Fair ang alok','Fair offer')}</b><p>${t('AI price check','AI price check')}: ${money(o.price)}/kg ${low?t('ay mas mababa sa','is below'):t('ay pasok sa o higit sa','meets or exceeds')} ${money(o.fairMinimum||0)}/kg.</p><small>${o.assessmentSource==='ai-estimate'?t('Batay sa AI estimate ng listing','Based on the listing AI estimate'):t('Batay sa listing price reference','Based on the listing price reference')}</small></div>`}
function deliveryName(method){return ({partner:t('Delivery Partner','Delivery Partner'),coop:t('Cooperative Transport','Cooperative Transport'),pickup:t('Buyer Pickup','Buyer Pickup')})[method]||method}
function paymentBreakdown(o){const p=o.payment;if(!p)return '';return `<section class="payment-breakdown"><h3>${t('Payment breakdown','Payment breakdown')}</h3><div><span>${t('Farmer receives','Farmer receives')}</span><b>${money(p.farmerReceives)}</b></div>${p.deliveryDiscount>0?`<div><span>${t('Pro/Enterprise delivery discount','Pro/Enterprise delivery discount')}</span><b>−${money(p.deliveryDiscount)}</b></div>`:''}<div><span>${t('Buyer pays produce + delivery','Buyer pays produce + delivery')}</span><b>${money(p.buyerTotal)}</b></div><div><span>${t('Logistics/transport receives','Logistics/transport receives')}</span><b>${money(p.providerReceives)}</b></div><div><span>AgrikAIzen (${p.commissionRate}%)</span><b>${money(p.agrikaizenCommission)}</b></div><p class="notice">${p.deliveryDiscount>0?t('Ang delivery discount ay mula sa pag-waive ng 5% platform commission; buo pa rin ang normal na net fee ng logistics partner.','The delivery discount comes from waiving the 5% platform commission; the logistics partner keeps its normal net fee.'):t('Settlement record lamang ito. Walang aktwal na payment transfer sa prototype.','This is a settlement record. The prototype does not transfer funds.')}</p></section>`}
function deliveryPanel(o,farmer,buyer){if(o.status!=='accepted')return '';if(o.transactionStatus==='confirmed'&&farmer)return `<section class="delivery-choice"><h3>${t('Sino ang maghahatid?','Who will deliver?')}</h3><div class="delivery-grid"><button onclick="selectDelivery('${o.id}','partner',this)">🚚<b>${t('Delivery Partner','Delivery Partner')}</b></button><button onclick="selectDelivery('${o.id}','coop',this)">🤝<b>${t('Cooperative Transport','Cooperative Transport')}</b></button><button onclick="selectDelivery('${o.id}','pickup',this)">🏢<b>${t('Buyer Pickup','Buyer Pickup')}</b></button></div></section>`;if(!o.delivery)return '';const d=o.delivery;return `<section class="delivery-summary"><h3>${deliveryName(d.method)}</h3><p>${t('Status','Status')}: <b>${transactionStatusName(o.transactionStatus)}</b></p>${d.providerName?`<p>${t('Tagapaghatid','Provider')}: ${esc(d.providerName)}</p>`:''}${Number.isFinite(d.fee)?`<p>${t('Delivery fee','Delivery fee')}: ${money(d.fee)}</p>`:''}${buyer&&d.method==='pickup'&&d.status==='awaiting_provider'?`<button class="btn wide" onclick="acceptDelivery('${o.id}',this,0)">${t('Kumpirmahin ang pickup','Accept pickup job')}</button>`:''}</section>`}
function offerCard(o){const farmer=state.user.role==='farmer',buyer=state.user.role==='buyer';return `<article class="card transaction-card" id="offer-${esc(o.id)}"><div class="crop-product-head">${cropPhotoById(o.crop,'crop-card-photo')}<div class="grow"><div class="row between"><h3>${esc(o.variety)}</h3><span class="pill">${transactionStatusName(o.transactionStatus||o.status)}</span></div><small>${esc(cropName(o.crop))}</small></div></div><p>${esc(o.buyer)} · ${esc(o.location)}</p><p>${o.quantity} kg × <b>${money(o.price)}/kg</b></p><p>${t('Halaga ng ani','Produce total')}: ${money(o.quantity*o.price)}</p>${assessmentPanel(o)}${o.counterPrice?`<p>${t('Kontra-alok','Counter-offer')}: <b>${money(o.counterPrice)}/kg</b></p>`:''}${farmer&&o.status==='pending'?`<div class="offer-actions"><button class="btn" onclick="respondOffer('${o.id}','accepted',this)">${t('Tanggapin','Accept')}</button><button class="btn danger" onclick="respondOffer('${o.id}','rejected',this)">${t('Tanggihan','Reject')}</button></div>${o.assessment==='low'?`<form onsubmit="counterOffer(event,'${o.id}')">${field(t('Kontra-alok (₱/kg)','Counter price (₱/kg)'),`counter-${o.id}`,'number',o.fairMinimum||'','min="0.01" max="1000000000" step="0.01"')}<button class="btn soft wide">${t('Ipadala ang kontra-alok','Send counter-offer')}</button></form>`:''}`:''}${buyer&&o.status==='countered'?`<div class="offer-actions"><button class="btn" onclick="respondCounter('${o.id}','accepted',this)">${t('Tanggapin ang kontra-alok','Accept counter')}</button><button class="btn danger" onclick="respondCounter('${o.id}','rejected',this)">${t('Tanggihan','Reject')}</button></div>`:''}${deliveryPanel(o,farmer,buyer)}${paymentBreakdown(o)}</article>`}
function pushEnvironmentIssue(){if(typeof navigator==='undefined'||typeof window==='undefined')return '';const ua=navigator.userAgent||'';if(/FBAN|FBAV|Instagram|Messenger/i.test(ua))return t('Hindi makapag-register ng push notification ang browser sa loob ng Messenger. Pindutin ang ⋯ sa itaas at piliin ang Open in Chrome.','The browser inside Messenger cannot register push notifications. Tap ⋯ above and choose Open in Chrome.');if(/iPhone|iPad|iPod/i.test(ua)&&!window.navigator.standalone)return t('Sa iPhone/iPad, buksan ito sa Safari at piliin ang Add to Home Screen bago i-enable ang notifications.','On iPhone/iPad, open this in Safari and choose Add to Home Screen before enabling notifications.');if(!window.isSecureContext)return t('Kailangan ang secure HTTPS page para sa push notifications.','Push notifications require a secure HTTPS page.');return ''}
function notificationControl(){if(state.user.demo)return `<p class="notice">${t('Sa deployed HTTPS app, puwedeng i-enable ang browser push notifications.','Browser push can be enabled in the deployed HTTPS app.')}</p>`;const issue=pushEnvironmentIssue();if(issue)return `<div class="notice push-guidance"><b>${t('Buksan sa tamang browser','Open in a supported browser')}</b><span>${issue}</span></div>`;return `<button class="btn soft wide" onclick="enablePush(this)">${icon('bell')}<span class="btn-label">${t('I-enable ang push notifications','Enable push notifications')}</span></button>`}
function offersPage(){const list=myOffers(),farmer=state.user.role==='farmer';return `<section class="page soft-page">${pageTop(farmer?t('Mga Alok ng Buyer','Buyer offers'):t('Aking mga Deal','My deals'))}${marketNotice()}${notificationControl()}<button class="btn ghost wide" onclick="refreshMarket();render()">${t('I-refresh ang mga update','Refresh updates')}</button>${list.length?list.map(offerCard).join(''):emptyState()}</section>`}
async function respondOffer(id,status,button,price){if(state.responding)return;state.responding=true;button.disabled=true;try{await marketWrite({action:'respond',id,status,price});await refreshMarket();render();toast(t('Na-save ang tugon.','Response saved.'))}catch(e){toast(e.message)}finally{state.responding=false;button.disabled=false}}
function counterOffer(e,id){e.preventDefault();respondOffer(id,'countered',e.target.querySelector('button'),Number($(`#counter-${id}`).value))}
async function respondCounter(id,status,button){button.disabled=true;try{await marketWrite({action:'respondCounter',id,status});await refreshMarket();render();toast(t('Na-save ang tugon.','Response saved.'))}catch(e){toast(e.message)}finally{button.disabled=false}}
async function selectDelivery(id,deliveryMethod,button){button.disabled=true;try{await marketWrite({action:'selectDelivery',id,deliveryMethod});await refreshMarket();render();toast(t('Napili ang paraan ng delivery.','Delivery method selected.'))}catch(e){toast(e.message)}finally{button.disabled=false}}
