async function deliveryAction(id,action,button,fee){button.disabled=true;try{await marketWrite({action,id,fee:Number(fee)});await refreshMarket();render();toast(t('Na-update ang delivery.','Delivery updated.'))}catch(e){toast(e.message)}finally{button.disabled=false}}
function logisticsJobCard(o){const d=o.delivery,assigned=d?.providerId===state.user.id;return `<article class="card transaction-card"><div class="crop-product-head">${cropPhotoById(o.crop,'crop-card-photo')}<div class="grow"><div class="row between"><h3>${esc(o.variety)}</h3><span class="pill">${transactionStatusName(o.transactionStatus)}</span></div><small>${esc(cropName(o.crop))}</small></div></div><p>${o.quantity} kg · ${esc(o.location)}</p><p>${deliveryName(d.method)}</p>${d.status==='awaiting_provider'?`<form onsubmit="event.preventDefault();acceptDelivery('${o.id}',this.querySelector('button'),${d.method==='pickup'?0:`Number(this.querySelector('input').value)`})">${d.method==='pickup'?'':field(t('Delivery fee (₱)','Delivery fee (₱)'),`delivery-fee-${o.id}`,'number','','min="0.01" max="1000000000" step="0.01"')}<button class="btn wide">${t('Tanggapin ang job','Accept job')}</button></form>`:assigned&&d.status==='accepted'?`<button class="btn wide" onclick="deliveryAction('${o.id}','startDelivery',this)">${t('Simulan ang delivery','Start delivery')}</button>`:assigned&&d.status==='in_progress'?`<button class="btn wide" onclick="deliveryAction('${o.id}','completeDelivery',this)">${t('Markahan bilang delivered','Mark delivered')}</button>`:''}${paymentBreakdown(o)}</article>`}
function logisticsPage(){const role=state.user.role,method=role==='coop'?'coop':role==='logistics'?'partner':'pickup',jobs=marketData().offers.filter(o=>o.delivery?.method===method&&(!o.delivery.providerId||o.delivery.providerId===state.user.id));return `<section class="page soft-page">${role==='logistics'?header():pageTop(t('Transport Jobs','Transport jobs'))}${marketNotice()}${notificationControl()}<section class="card"><h2>${t('Mga delivery job','Delivery jobs')}</h2><p class="muted">${t('Ang fee ay may 5% AgrikAIzen commission, nasa loob ng 3–8% range sa business plan.','The fee uses a 5% AgrikAIzen commission, within the business plan’s 3–8% range.')}</p></section>${jobs.length?jobs.map(logisticsJobCard).join(''):emptyState()}</section>`}
function urlKey(value){const padding='='.repeat((4-value.length%4)%4),base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64);return Uint8Array.from([...raw].map(x=>x.charCodeAt(0)))}
function samePushKey(subscription,key){const current=subscription?.options?.applicationServerKey;if(!current)return true;const bytes=new Uint8Array(current);return bytes.length===key.length&&bytes.every((value,index)=>value===key[index])}
function pushErrorMessage(error){const message=String(error?.message||error||'');if(/push service error|registration failed|aborterror/i.test(message))return t('Hindi makakonekta ang browser sa push service. Buksan ang app sa Chrome o Safari, huwag sa browser sa loob ng Messenger, at subukan muli.','The browser could not connect to its push service. Open the app in Chrome or Safari instead of the browser inside Messenger, then try again.');if(/notallowed|permission|denied/i.test(`${error?.name||''} ${message}`))return t('Naka-block ang notifications. Payagan ito sa browser Site settings, saka subukan muli.','Notifications are blocked. Allow them in the browser Site settings, then try again.');if(/applicationserverkey|vapid|65 bytes|base64/i.test(message))return t('May mali sa VAPID public key sa Vercel. Gumawa at ilagay muli ang magkaparehong public at private VAPID keys.','The VAPID public key in Vercel is invalid. Generate and save a matching public and private VAPID key pair.');return message||t('Hindi ma-enable ang push notifications sa ngayon.','Push notifications could not be enabled right now.')}
async function enablePush(button){const environmentIssue=pushEnvironmentIssue();if(environmentIssue)return toast(environmentIssue);if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))return toast(t('Hindi suportado ng browser ang push. Buksan ang app sa Chrome o Safari.','Push is not supported by this browser. Open the app in Chrome or Safari.'));button.disabled=true;try{const key=await api('/api/push',{action:'key'});if(!key.configured)throw new Error(t('Hindi pa naka-configure ang VAPID keys sa Vercel.','VAPID keys are not configured in Vercel.'));const permission=await Notification.requestPermission();if(permission!=='granted')throw new DOMException(t('Hindi pinayagan ang notifications.','Notification permission was not granted.'),'NotAllowedError');await navigator.serviceWorker.register('/sw.js');const registration=await navigator.serviceWorker.ready,applicationServerKey=urlKey(key.publicKey);let subscription=await registration.pushManager.getSubscription();if(subscription&&!samePushKey(subscription,applicationServerKey)){await subscription.unsubscribe();subscription=null}subscription=subscription||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey});await api('/api/push',{action:'subscribe',subscription:subscription.toJSON()});toast(t('Naka-on na ang push notifications.','Push notifications enabled.'));render()}catch(error){toast(pushErrorMessage(error))}finally{button.disabled=false}}
function premiumTab(id,label){return `<button class="${(state.premiumTab||'source')===id?'active':''}" onclick="state.premiumTab='${id}';render()">${label}</button>`}
function buyerTier(){const data=marketData();return data.subscriptionTier||(data.premium?'enterprise':null)}
function enterpriseBuyer(){return buyerTier()==='enterprise'}
function togglePremiumPlans(){state.showPremiumPlans=!state.showPremiumPlans;render()}
async function chooseSubscription(plan,button){
  if(!['pro','enterprise'].includes(plan))return;
  if(state.user.demo){state.demoBuyerTier=plan;state.showPremiumPlans=false;state.premiumTab='source';render();return toast(t(`Demo preview: ${plan==='pro'?'Pro':'Enterprise'} plan.`,`Demo preview: ${plan==='pro'?'Pro':'Enterprise'} plan.`))}
  const oldText=button?.textContent;if(button){button.disabled=true;button.textContent=t('Sine-save…','Saving…')}
  try{
    const result=await api('/api/subscription',{action:'choose',plan}),data=marketData();
    Object.assign(data,{requestedPlan:result.requestedPlan,subscriptionStatus:result.subscriptionStatus,subscriptionRequestedAt:result.subscriptionRequestedAt});
    render();toast(t('Napili ang plan. Pending ang payment setup.','Plan selected. Payment setup is pending.'));
  }catch(error){toast(error.message);if(button){button.disabled=false;button.textContent=oldText}}
}
function premiumPage(){
  const tier=buyerTier(),unlocked=Boolean(tier)&&state.user.role==='buyer',enterprise=tier==='enterprise',tab=state.premiumTab||'source',showPlans=!unlocked||state.showPremiumPlans;
  const body=showPlans?premiumLocked():tab==='market'?premiumMarketIntelligence():tab==='suppliers'?premiumSuppliers():enterprise&&tab==='alerts'?premiumAlerts():enterprise&&tab==='orders'?premiumOrders():enterprise&&tab==='insights'?premiumInsights():premiumSourcing();
  return `<section class="page soft-page">${pageTop(t('Buyer Subscription','Buyer Subscription'))}<section class="premium-hero"><span>✦ ${unlocked?`${tier.toUpperCase()} ${t('PLAN','PLAN')}`:t('Mga procurement plan','Procurement plans')}</span><h2>${t('Mas mabilis na sourcing, malinaw na desisyon','Source faster and decide with confidence')}</h2><p>${t('Libre pa rin ang marketplace. Piliin ang planong naaayon sa laki at dalas ng inyong pagbili.','The marketplace stays free. Choose the plan that fits your purchasing volume and frequency.')}</p>${unlocked?`<button class="link premium-plan-link" onclick="togglePremiumPlans()">${showPlans?t('Bumalik sa workspace','Return to workspace'):t('Tingnan ang mga plan','View plans')}</button>`:''}</section>${marketNotice()}${unlocked&&!showPlans?`<div class="tabs premium-tabs">${premiumTab('source',t('Sourcing','Sourcing'))}${premiumTab('market',t('Presyo','Prices'))}${premiumTab('suppliers',t('Suppliers','Suppliers'))}${enterprise?`${premiumTab('alerts',t('Alerts','Alerts'))}${premiumTab('orders',t('Regular','Recurring'))}${premiumTab('insights',t('Analytics','Analytics'))}`:''}</div>`:''}${body}</section>`;
}
function premiumLocked(){const pro=[
  ['⌕','Smart Sourcing',t('Ilagay ang produkto, dami, target price, petsa, at layo upang awtomatikong makita ang tugmang ani.','Enter product, quantity, target price, required date, and distance to automatically find matching harvests.')],
  ['⚙','Advanced Supplier Search',t('Salain ayon sa price range, dami, harvest date, grade, farming method, distance, at availability.','Filter by price range, quantity, harvest date, grade, farming method, distance, and availability.')],
  ['⇄','Supplier Comparison',t('Ihambing ang presyo, available quantity, layo, at tinatayang transport cost.','Compare price, available quantity, distance, and estimated transport cost.')],
  ['↗','Market Price Intelligence',t('Tingnan ang current at historical prices, regional comparison, at seasonal trends.','View current and historical prices, regional comparisons, and seasonal trends.')],
  ['♙','Supplier Management',t('I-save ang supplier at subaybayan ang orders, purchase frequency, at transaction records.','Save suppliers and monitor orders, purchase frequency, and transaction records.')],
  ['○','Ad-Free Experience',t('Walang sponsored advertisements o promotional content sa Pro at Enterprise workspace.','Use the Pro and Enterprise workspace without sponsored advertisements or promotional content.')],
  ['₱','Discounted Delivery Fees',t('Makakuha ng 5% bawas sa eligible delivery sa pamamagitan ng pag-waive ng platform commission.','Receive 5% off eligible deliveries by waiving the platform commission.')]
],enterprise=[
  ['▦','Bulk Sourcing',t('Magpadala ng isang purchasing request sa maraming tugmang magsasaka.','Send one purchasing request to multiple matching farmers.')],
  ['♢','Harvest Alerts',t('Gumawa ng alert ayon sa crop, dami, presyo, lokasyon, at harvest period.','Create alerts by crop, quantity, price, location, and harvest period.')],
  ['↻','Recurring Orders',t('Mag-set ng weekly, every-two-weeks, o monthly purchasing schedule.','Set weekly, every-two-weeks, or monthly purchasing schedules.')],
  ['▥','Business Procurement Analytics',t('Subaybayan ang gastos, average price, madalas bilhing produkto, at supplier activity.','Monitor spending, average prices, frequently purchased products, and supplier activity.')],
  ['⇩','Exportable Records',t('I-download ang transaction at procurement records bilang CSV para sa accounting at reports.','Download transaction and procurement records as CSV for accounting and reports.')]
];const data=marketData(),active=buyerTier(),pending=data.subscriptionStatus==='pending_payment'?data.requestedPlan:null,planButton=(plan,price)=>{const current=active===plan,waiting=pending===plan,label=current?t('Kasalukuyang plan','Current plan'):waiting?t('Napili — hinihintay ang payment','Selected — payment pending'):state.user.demo?t(`I-preview ang ${plan==='pro'?'Pro':'Enterprise'}`,`Preview ${plan==='pro'?'Pro':'Enterprise'}`):t(`Piliin ang ${plan==='pro'?'Pro':'Enterprise'} — ₱${price}/buwan`,`Choose ${plan==='pro'?'Pro':'Enterprise'} — ₱${price}/month`);return `<button class="btn wide tier-select" ${current||waiting?'disabled':''} onclick="chooseSubscription('${plan}',this)">${label}</button>`};return `<section class="tier-intro"><h2>${t('Pumili ng planong pang-negosyo','Choose a business plan')}</h2><p>${t('Malinaw ang paghahati ng mga tool upang ang negosyo ay magbayad lamang para sa kailangan nito.','Features are grouped clearly so each business pays only for what it needs.')}</p></section>${pending?`<div class="subscription-pending"><b>${t('Napiling plan','Selected plan')}: ${pending.toUpperCase()}</b><span>${t('Naka-save ang pagpili mo. Hinihintay pa ang payment setup bago ma-activate ang premium tools.','Your choice is saved. Payment setup is still required before premium tools are activated.')}</span></div>`:''}<div class="tier-grid"><article class="card tier-card pro-tier ${active==='pro'?'current':''}"><span class="tier-label">PRO</span><h2>₱149<small>/${t('buwan','month')}</small></h2><p>${t('Para sa independent restaurants, cafés, at maliliit na retailer.','For independent restaurants, cafés, and small retailers.')}</p>${planButton('pro',149)}<ul>${pro.map(([i,name,description])=>`<li><span>${i}</span><div><b>${name}</b><small>${description}</small></div></li>`).join('')}</ul></article><article class="card tier-card enterprise-tier ${active==='enterprise'?'current':''}"><span class="tier-label">ENTERPRISE</span><h2>₱499<small>/${t('buwan','month')}</small></h2><p>${t('Para sa supermarket, hotel, food processor, at multi-location o high-volume buyer.','For supermarkets, hotels, food processors, and multi-location or high-volume buyers.')}</p>${planButton('enterprise',499)}<div class="all-pro">✓ ${t('Lahat ng Pro features, kasama ang:','Everything in Pro, plus:')}</div><ul>${enterprise.map(([i,name,description])=>`<li><span>${i}</span><div><b>${name}</b><small>${description}</small></div></li>`).join('')}</ul></article></div><p class="notice">${state.user.demo?t('Sa Demo Mode, agad na nabubuksan ang preview ng napiling plan.','In Demo Mode, the selected plan preview opens immediately.'):t('Ang pagpili ng plan ay nagse-save ng subscription request. Maa-activate lamang ang premium tools pagkatapos makumpleto ang payment at account provisioning.','Choosing a plan saves a subscription request. Premium tools activate only after payment and account provisioning are completed.')}</p><button class="btn soft wide" onclick="go('harvests')">${t('Gamitin ang libreng marketplace','Use free marketplace')}</button>`}
function premiumSourcing(){const m=state.premiumMatches||[], selected=state.compareIds||[], supply=m.reduce((n,x)=>n+x.quantity,0);return `<section class="card"><div class="eyebrow">Smart Sourcing + Advanced Search</div><h2>${t('Hanapin ang tamang supply','Find the right supply')}</h2><form onsubmit="autoMatch(event)"><div class="field"><label for="matchCrop">${t('Produkto','Product')}</label><select id="matchCrop">${cropOptions(state.matchCriteria?.crop)}</select></div>${field(t('Kailangang dami (kg)','Required quantity (kg)'),'matchQuantity','number',state.matchCriteria?.quantity||'','min="1" max="1000000000" step="0.01"')}<div class="two-col">${field(t('Min ₱/kg','Min ₱/kg'),'matchMinPrice','number',state.matchCriteria?.minimumPrice||0.01,'min="0.01" max="1000000000" step="0.01"')}${field(t('Target max (₱/kg)','Target max (₱/kg)'),'matchPrice','number',state.matchCriteria?.price||'','min="0.01" max="1000000000" step="0.01"')}</div><div class="two-col">${field(t('Kailangan bago','Required by'),'matchDate','date',state.matchCriteria?.requiredDate||'')}${field(t('Preferred distance (km)','Preferred distance (km)'),'matchDistance','number',state.matchCriteria?.distance||50,'min="1" max="10000" step="1"')}</div><div class="two-col"><div class="field"><label for="matchQuality">${t('Grade','Grade')}</label><select id="matchQuality"><option value="any">${t('Anuman','Any')}</option><option value="premium">Grade A</option><option value="standard">Grade B</option><option value="low">Grade C</option></select></div><div class="field"><label for="matchMethod">${t('Paraan','Method')}</label><select id="matchMethod"><option value="any">${t('Anuman','Any')}</option><option value="conventional">${t('Karaniwan','Conventional')}</option><option value="organic">${t('Organiko','Organic')}</option><option value="natural">Natural</option></select></div></div><button class="btn wide">${t('Awtomatikong itugma','Find matches')}</button></form></section>${m.length?`<section class="card forecast-strip"><div><b>${m.length}</b><span>${t('supplier','suppliers')}</span></div><div><b>${supply} kg</b><span>${t('nakalistang supply','listed supply')}</span></div><div><b>${money(Math.min(...m.map(x=>x.price)))}</b><span>${t('pinakamababang presyo','lowest price')}</span></div></section>${state.distanceNotice?`<p class="notice">${t('May supplier na walang verified distance. Hindi sila inalis ng distance filter.','Some suppliers have no verified distance and were not excluded by the distance filter.')}</p>`:''}${m.map(premiumMatchCard).join('')}${selected.length?comparisonPanel(m.filter(x=>selected.includes(x.id))):''}`:state.premiumSearched?emptyState():`<p class="notice">${t('Ilagay ang crop, dami, presyo, petsa, at layo. Lalabas dito ang future harvests na tugma.','Enter crop, quantity, price, date, and distance to see matching future harvests.')}</p>`}`}
function premiumMatchCard(l){const checked=(state.compareIds||[]).includes(l.id);return `<article class="card match-card"><div class="row between"><span class="pill">${l.matchScore||'—'}% ${t('tugma','match')}</span><small>${(l.matchReasons||[]).map(esc).join(' · ')}</small></div><label class="compare-check"><input type="checkbox" ${checked?'checked':''} onchange="toggleCompare('${l.id}')"> ${enterpriseBuyer()?t('Ihambing / isama sa bulk','Compare / include in bulk'):t('Ihambing ang supplier','Compare supplier')}</label>${listingCard(l,false)}</article>`}
function comparisonPanel(list){const rate=12,qty=state.matchCriteria?.quantity||0;return `<section class="card"><div class="eyebrow">${t('Supplier comparison','Supplier comparison')}</div><div class="table-wrap"><table><thead><tr><th>${t('Supplier','Supplier')}</th><th>₱/kg</th><th>${t('Available','Available')}</th><th>km</th><th>${t('Transport','Transport')}</th><th>${t('Kabuuang sourcing','Sourcing total')}</th></tr></thead><tbody>${list.map(l=>{const transport=l.distance?l.distance*rate:null,total=qty*l.price+(transport||0);return `<tr><td>${esc(l.farmer)}</td><td>${money(l.price)}</td><td>${l.availableQuantity??l.quantity} kg</td><td>${l.distance??'—'}</td><td>${transport?money(transport):t('Kailangan ng layo','Needs distance')}</td><td>${transport?money(total):t('Hindi pa kumpleto','Incomplete')}</td></tr>`}).join('')}</tbody></table></div><p class="notice">${t('Halimbawang transport estimate: ₱12/km bawat biyahe. Kumpirmahin ang aktwal na rate at ruta.','Illustrative transport estimate: ₱12/km per trip. Confirm the actual rate and route.')}</p>${enterpriseBuyer()?`<form onsubmit="bulkOffer(event)">${field(t('Kabuuang dami (kg)','Total quantity (kg)'),'bulkQuantity','number',state.matchCriteria?.quantity||'','min="1" max="1000000000" step="0.01"')}${field(t('Alok (₱/kg)','Offer (₱/kg)'),'bulkPrice','number',state.matchCriteria?.price||'','min="0.01" max="1000000000" step="0.01"')}${field(t('Kailangang petsa','Required date'),'bulkDate','date',state.matchCriteria?.requiredDate||'')}<button class="btn wide">${t('Magpadala ng isang bulk request','Send one bulk request')}</button></form>`:`<p class="enterprise-upsell">🔒 ${t('Ang pagpapadala sa maraming supplier sa isang request ay kasama sa Enterprise plan.','Sending one request to multiple suppliers is included in the Enterprise plan.')}</p>`}</section>`}
async function autoMatch(e){e.preventDefault();const b=e.target.querySelector('button'),criteria={crop:$('#matchCrop').value,quantity:Number($('#matchQuantity').value),minimumPrice:Number($('#matchMinPrice').value),price:Number($('#matchPrice').value),requiredDate:$('#matchDate').value,distance:Number($('#matchDistance').value),quality:$('#matchQuality').value,farmingMethod:$('#matchMethod').value};b.disabled=true;try{let data;if(state.user.demo){let matches=marketData().listings.filter(l=>l.status==='available'&&l.crop===criteria.crop&&l.quantity>=criteria.quantity&&l.price>=criteria.minimumPrice&&l.price<=criteria.price&&l.harvestDate<=criteria.requiredDate&&(criteria.quality==='any'||l.quality===criteria.quality)&&(criteria.farmingMethod==='any'||l.farmingMethod===criteria.farmingMethod)&&(!l.distance||l.distance<=criteria.distance)).sort((a,b)=>a.price-b.price);data={matches,distanceNotice:matches.some(l=>!l.distance)}}else data=await api('/api/market',{action:'match',...criteria});state.matchCriteria=criteria;state.premiumMatches=data.matches;state.distanceNotice=data.distanceNotice;state.compareIds=[];state.premiumSearched=true;render()}catch(error){toast(error.message)}finally{b.disabled=false}}
function toggleCompare(id){state.compareIds=state.compareIds||[];state.compareIds=state.compareIds.includes(id)?state.compareIds.filter(x=>x!==id):[...state.compareIds,id];render()}
async function bulkOffer(e){e.preventDefault();const listingIds=state.compareIds||[];if(!listingIds.length)return;await submitMarketForm(e,{action:'bulkOffer',listingIds,quantity:Number($('#bulkQuantity').value),price:Number($('#bulkPrice').value),requiredDate:$('#bulkDate').value},t('Naipadala ang bulk request.','Bulk request sent.'));state.compareIds=[];state.premiumMatches=[];render()}
function premiumAlerts(){const alerts=marketData().alerts;return `<section class="card"><div class="eyebrow">Harvest Alerts</div><h2>${t('Maagang abiso sa bagong ani','Early notice for new harvests')}</h2><form onsubmit="createAlert(event)"><div class="field"><label for="alertCrop">${t('Pananim','Crop')}</label><select id="alertCrop">${cropOptions()}</select></div><div class="two-col">${field(t('Dami (kg)','Quantity (kg)'),'alertQuantity','number','','min="1" max="1000000000" step="0.01"')}${field(t('Max ₱/kg','Max ₱/kg'),'alertPrice','number','','min="0.01" max="1000000000" step="0.01"')}</div>${field(t('Lokasyon','Location'),'alertLocation','text',state.user.location,'maxlength="100"')}<div class="two-col">${field(t('Mula','From'),'alertFrom','date','')}${field(t('Hanggang','To'),'alertTo','date','')}</div><button class="btn wide">${t('Gumawa ng alert','Create alert')}</button></form></section>${alerts.length?alerts.map(a=>`<article class="card"><div class="crop-product-head">${cropPhotoById(a.crop,'crop-card-photo')}<div class="grow"><div class="row between"><h3>${esc(cropName(a.crop))}</h3><button class="link" onclick="deleteAlert('${a.id}')">${t('Burahin','Delete')}</button></div><p>${a.quantity} kg · ≤ ${money(a.maximumPrice)}/kg</p></div></div><p class="muted">${esc(a.location)} · ${esc(a.fromDate)} – ${esc(a.toDate)}</p><span class="pill">${alertMatches(a)} ${t('kasalukuyang tugma','current matches')}</span></article>`).join(''):emptyState()}`}
function alertMatches(a){return marketData().listings.filter(l=>l.crop===a.crop&&l.quantity>=a.quantity&&l.price<=a.maximumPrice&&l.harvestDate>=a.fromDate&&l.harvestDate<=a.toDate).length}
function createAlert(e){return submitMarketForm(e,{action:'createAlert',crop:$('#alertCrop').value,quantity:Number($('#alertQuantity').value),maximumPrice:Number($('#alertPrice').value),location:$('#alertLocation').value.trim(),fromDate:$('#alertFrom').value,toDate:$('#alertTo').value},t('Naka-on na ang harvest alert.','Harvest alert created.'))}
async function deleteAlert(id){try{await marketWrite({action:'deleteAlert',id});await refreshMarket();render();toast(t('Binura ang alert.','Alert deleted.'))}catch(e){toast(e.message)}}
async function toggleSupplier(farmerId){try{await marketWrite({action:'toggleSupplier',farmerId});await refreshMarket();render()}catch(e){toast(e.message)}}
function premiumMarketIntelligence(){const data=marketData(),completed=data.offers.filter(o=>o.status==='accepted'),byCrop=crops.map(c=>{const listings=data.listings.filter(l=>l.crop===c.id),purchases=completed.filter(o=>o.crop===c.id),prices=[...listings.map(l=>l.price),...purchases.map(o=>o.price)];return {name:cropName(c.id),count:prices.length,avg:prices.length?prices.reduce((n,p)=>n+p,0)/prices.length:0}}).filter(x=>x.count),byRegion=Object.entries(data.listings.reduce((a,l)=>{const r=a[l.location]||(a[l.location]={total:0,count:0});r.total+=l.price;r.count++;return a},{})).sort((a,b)=>a[0].localeCompare(b[0])),history=Object.entries(completed.reduce((a,o)=>{const k=(o.createdAt||'').slice(0,7)||t('Walang petsa','No date'),r=a[k]||(a[k]={total:0,kg:0,count:0});r.total+=o.price*o.quantity;r.kg+=o.quantity;r.count++;return a},{})).sort(),seasonal=Object.entries(data.listings.reduce((a,l)=>{const month=l.harvestDate?.slice(0,7)||t('Walang petsa','No date'),r=a[month]||(a[month]={qty:0,total:0,count:0});r.qty+=l.availableQuantity??l.quantity;r.total+=l.price;r.count++;return a},{})).sort();return `<section class="card"><div class="eyebrow">Market Price Intelligence · PRO</div><h2>${t('Kasalukuyang presyo','Current market prices')}</h2><p class="notice">${t('Pinagsasama nito ang kasalukuyang app listings at accepted orders. Ang opisyal na PSA farmgate data ay makikita sa Market Intelligence page.','This combines current app listings and accepted orders. Official PSA farmgate observations are available on the Market Intelligence page.')}</p>${byCrop.length?byCrop.map(x=>`<div class="metric-row"><span>${esc(x.name)} · ${x.count} ${t('record','records')}</span><b>${money(x.avg)}/kg</b></div>`).join(''):emptyState()}</section><section class="card"><h2>${t('Paghahambing ayon sa rehiyon','Regional price comparison')}</h2>${byRegion.length?byRegion.map(([region,r])=>`<div class="metric-row"><span>${esc(region)}</span><b>${money(r.total/r.count)}/kg</b></div>`).join(''):emptyState()}</section><section class="card"><h2>${t('Historical purchase prices','Historical purchase prices')}</h2>${history.length?history.map(([month,r])=>`<div class="metric-row"><span>${esc(month)} · ${r.count} ${t('order','orders')}</span><b>${money(r.total/r.kg)}/kg</b></div>`).join(''):`<p class="empty">${t('Lalabas dito ang history pagkatapos ng accepted orders.','History appears after orders are accepted.')}</p>`}</section><section class="card"><h2>${t('Seasonal price at supply trend','Seasonal price and supply trend')}</h2>${seasonal.length?seasonal.map(([month,r])=>`<div class="metric-row"><span>${esc(month)} · ${r.qty} kg</span><b>${money(r.total/r.count)}/kg</b></div>`).join(''):emptyState()}</section>`}
function premiumSuppliers(){const data=marketData(),suppliers=data.suppliers;return `<section class="card"><div class="eyebrow">Supplier Management · PRO</div><h2>${t('Mga paboritong supplier','Preferred suppliers')}</h2><p>${t('I-save ang supplier mula sa listing o sourcing results. Makikita rito ang previous orders, purchase frequency, at transaction records.','Save suppliers from listings or sourcing results. Previous orders, purchase frequency, and transaction records appear here.')}</p></section>${suppliers.length?suppliers.map(s=>{const offers=data.offers.filter(o=>o.farmerId===s.farmerId),accepted=offers.filter(o=>o.status==='accepted'),spent=accepted.reduce((n,o)=>n+o.quantity*o.price,0),last=accepted.map(o=>o.createdAt).filter(Boolean).sort().at(-1);return `<article class="card"><div class="row between"><h3>${esc(s.farmer)}</h3><button class="link" onclick="toggleSupplier('${s.farmerId}')">${t('Alisin','Remove')}</button></div><p class="muted">${esc(s.location)}</p><div class="supplier-stats"><div><b>${accepted.length}</b><span>${t('Previous orders','Previous orders')}</span></div><div><b>${accepted.reduce((n,o)=>n+o.quantity,0)} kg</b><span>${t('Nabili','Purchased')}</span></div><div><b>${money(spent)}</b><span>${t('Kabuuang halaga','Total spend')}</span></div></div><p class="small">${t('Purchase frequency','Purchase frequency')}: <b>${accepted.length?t(`${accepted.length} order sa record`,`${accepted.length} recorded orders`):t('Wala pa','None yet')}</b>${last?` · ${t('Huling order','Last order')}: ${esc(last.slice(0,10))}`:''}</p></article>`}).join(''):emptyState()}`}
function premiumOrders(){const orders=marketData().recurring;return `<section class="card"><div class="eyebrow">Recurring Orders</div><h2>${t('Regular na pangangailangan','Regular purchasing schedules')}</h2><form onsubmit="createRecurring(event)"><div class="field"><label for="recurringCrop">${t('Pananim','Crop')}</label><select id="recurringCrop">${cropOptions()}</select></div><div class="two-col">${field(t('Dami (kg)','Quantity (kg)'),'recurringQuantity','number','','min="1" max="1000000000" step="0.01"')}${field(t('Max ₱/kg','Max ₱/kg'),'recurringPrice','number','','min="0.01" max="1000000000" step="0.01"')}</div><div class="field"><label for="recurringCadence">${t('Dalas','Frequency')}</label><select id="recurringCadence"><option value="weekly">${t('Lingguhan','Weekly')}</option><option value="biweekly">${t('Kada dalawang linggo','Every two weeks')}</option><option value="monthly">${t('Buwanan','Monthly')}</option></select></div>${field(t('Simula','Start date'),'recurringStart','date','')}<button class="btn wide">${t('Gumawa ng schedule','Create schedule')}</button></form></section>${orders.length?orders.map(o=>`<article class="card"><div class="crop-product-head">${cropPhotoById(o.crop,'crop-card-photo')}<div class="grow"><div class="row between"><h3>${esc(cropName(o.crop))}</h3><span class="pill">${o.active?t('Aktibo','Active'):t('Naka-pause','Paused')}</span></div><p>${o.quantity} kg · ${money(o.maximumPrice)}/kg · ${esc(o.cadence)}</p></div></div><p class="muted">${t('Simula','Starts')}: ${esc(o.startDate)}</p><button class="btn soft wide" onclick="toggleRecurring('${o.id}')">${o.active?t('I-pause','Pause'):t('I-resume','Resume')}</button></article>`).join(''):emptyState()}`}
function createRecurring(e){return submitMarketForm(e,{action:'createRecurring',crop:$('#recurringCrop').value,quantity:Number($('#recurringQuantity').value),maximumPrice:Number($('#recurringPrice').value),cadence:$('#recurringCadence').value,startDate:$('#recurringStart').value},t('Nagawa ang recurring order.','Recurring order created.'))}
async function toggleRecurring(id){try{await marketWrite({action:'toggleRecurring',id});await refreshMarket();render()}catch(e){toast(e.message)}}
function premiumInsights(){const data=marketData(),completed=data.offers.filter(o=>o.status==='accepted'),spend=completed.reduce((n,o)=>n+o.quantity*o.price,0),kg=completed.reduce((n,o)=>n+o.quantity,0),byCrop=Object.entries(completed.reduce((a,o)=>{const r=a[o.crop]||(a[o.crop]={orders:0,kg:0,total:0});r.orders++;r.kg+=o.quantity;r.total+=o.quantity*o.price;return a},{})).sort((a,b)=>b[1].kg-a[1].kg),bySupplier=Object.entries(completed.reduce((a,o)=>{const name=o.farmer||o.variety||t('Supplier','Supplier'),r=a[name]||(a[name]={orders:0,kg:0,total:0});r.orders++;r.kg+=o.quantity;r.total+=o.quantity*o.price;return a},{})).sort((a,b)=>b[1].total-a[1].total);return `<section class="card"><div class="eyebrow">Business Procurement Analytics · ENTERPRISE</div><div class="stat-grid"><div class="stat"><b>${money(spend)}</b><span>${t('Gastos sa pagbili','Purchase spend')}</span></div><div class="stat"><b>${completed.length}</b><span>${t('Orders','Orders')}</span></div><div class="stat"><b>${kg?money(spend/kg):'—'}</b><span>${t('Avg ₱/kg','Avg ₱/kg')}</span></div></div><button class="btn soft wide" onclick="exportRecords()">${t('I-export ang transaction records bilang CSV','Export transaction records as CSV')}</button></section><section class="card"><h2>${t('Madalas bilhing produkto','Frequently purchased products')}</h2>${byCrop.length?byCrop.map(([crop,r])=>`<div class="metric-row"><span>${esc(cropName(crop))} · ${r.orders} ${t('order','orders')}</span><b>${r.kg} kg · ${money(r.total)}</b></div>`).join(''):emptyState()}</section><section class="card"><h2>${t('Supplier activity','Supplier activity')}</h2>${bySupplier.length?bySupplier.map(([supplier,r])=>`<div class="metric-row"><span>${esc(supplier)} · ${r.orders} ${t('order','orders')}</span><b>${money(r.total)}</b></div>`).join(''):emptyState()}</section>`}
function exportRecords(){const rows=[['Date','Supplier','Crop','Quantity kg','Price PHP/kg','Status','Total PHP'],...marketData().offers.map(o=>[o.createdAt||'',o.variety||'',cropName(o.crop),o.quantity,o.price,o.status,(o.quantity*o.price).toFixed(2)])],csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='agrikaizen-procurement-records.csv';a.click();URL.revokeObjectURL(url);toast(t('Na-export ang records.','Records exported.'))}
if(typeof setInterval==='function')setInterval(()=>{if(state.user&&typeof document!=='undefined'&&!document.hidden)refreshMarket()},30000);
